import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import { manifestSource, packEntries, promptEntries } from '../gen-asset-manifest';

describe('manifestSource', () => {
  it('writes an empty map when there are no files', () => {
    expect(manifestSource('PACK_ASSETS', '`<packId>/<relative path>`', [])).toBe(
      [
        '/* eslint-disable */',
        '// GENERATED by tools/gen-asset-manifest.ts. Do not edit by hand. Run `npm run gen:assets`.',
        '// Maps `<packId>/<relative path>` to a bundled asset module (require()).',
        'export const PACK_ASSETS: Record<string, number> = {};',
        '',
      ].join('\n'),
    );
  });

  it('sorts entries and uses static require() calls', () => {
    const src = manifestSource('PROMPT_ASSETS', 'x', [
      ['en/welcome', './prompts/en/welcome.m4a'],
      ['as/welcome', './prompts/as/welcome.m4a'],
    ]);
    expect(src.indexOf('"as/welcome"')).toBeLessThan(src.indexOf('"en/welcome"'));
    expect(src).toContain('"as/welcome": require("./prompts/as/welcome.m4a"),');
  });
});

describe('scanning', () => {
  let dir: string;
  const touch = (rel: string) => {
    const f = path.join(dir, rel);
    fs.mkdirSync(path.dirname(f), { recursive: true });
    fs.writeFileSync(f, '');
  };

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'akhor-assets-'));
  });
  afterEach(() => {
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('collects pack audio and images, ignoring other files and folders', () => {
    touch('packs/asm-beng/audio/letters/ka.m4a');
    touch('packs/asm-beng/audio/.gitkeep');
    touch('packs/asm-beng/images/words/kol.webp');
    touch('packs/asm-beng/notes.txt');
    touch('packs/not-a-pack/audio/x.m4a');
    expect(packEntries(path.join(dir, 'packs'))).toEqual([
      ['asm-beng/audio/letters/ka.m4a', './asm-beng/audio/letters/ka.m4a'],
      ['asm-beng/images/words/kol.webp', './asm-beng/images/words/kol.webp'],
    ]);
  });

  it('collects flat voice prompts per language', () => {
    touch('prompts/en/welcome.m4a');
    touch('prompts/as/welcome.m4a');
    touch('prompts/as/.gitkeep');
    touch('prompts/as/old/welcome.m4a');
    expect(promptEntries(path.join(dir, 'prompts'))).toEqual([
      ['as/welcome', './prompts/as/welcome.m4a'],
      ['en/welcome', './prompts/en/welcome.m4a'],
    ]);
    expect(promptEntries(path.join(dir, 'missing'))).toEqual([]);
  });
});
